CREATE TABLE stream_dvr_policy(stream_id text PRIMARY KEY REFERENCES streaming_stream(id),policy jsonb NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE dvr_window(id text PRIMARY KEY,recording_id text NOT NULL UNIQUE REFERENCES recording(id),policy jsonb NOT NULL,policy_version integer NOT NULL CHECK(policy_version>0),state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','draining','disabled')),expires_at timestamptz,end_position integer,event_sequence integer NOT NULL DEFAULT 0,last_event_at timestamptz,last_start integer NOT NULL DEFAULT -1,last_end integer NOT NULL DEFAULT -1,delivered_bytes bigint NOT NULL DEFAULT 0 CHECK(delivered_bytes>=0));
CREATE INDEX dvr_window_state_idx ON dvr_window(state,expires_at);
CREATE TABLE dvr_segment_pin(recording_id text NOT NULL,position integer NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(recording_id,position),FOREIGN KEY(recording_id,position) REFERENCES recording_segment(recording_id,position));
CREATE INDEX dvr_pin_expiry_idx ON dvr_segment_pin(expires_at);
CREATE TABLE dvr_delivery_usage(id text PRIMARY KEY,window_id text NOT NULL REFERENCES dvr_window(id),bytes integer NOT NULL CHECK(bytes>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX dvr_delivery_retention_idx ON dvr_delivery_usage(created_at);
CREATE FUNCTION validate_dvr_parent() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM recording WHERE id=NEW.recording_id AND kind='buffer') THEN RAISE EXCEPTION 'DVR requires a shared buffer'; END IF; RETURN NEW; END $$;
CREATE TRIGGER dvr_parent_guard BEFORE INSERT OR UPDATE OF recording_id ON dvr_window FOR EACH ROW EXECUTE FUNCTION validate_dvr_parent();
ALTER TABLE webhook_event DROP CONSTRAINT webhook_event_type_check;
ALTER TABLE webhook_event ADD CONSTRAINT webhook_event_type_check CHECK(event_type IN ('room.created', 'room.started', 'room.ended', 'participant.joined', 'participant.left', 'participant.reconnected', 'track.published', 'track.unpublished', 'connection.degraded', 'connection.recovered', 'stream.created', 'stream.starting', 'stream.live', 'stream.reconnecting', 'stream.ended', 'stream.failed', 'broadcast.created', 'broadcast.starting', 'broadcast.live', 'broadcast.reconnecting', 'broadcast.output_degraded', 'broadcast.stopped', 'broadcast.failed', 'destination.created', 'destination.connected', 'destination.disconnected', 'destination.retrying', 'destination.failed', 'recording.started', 'recording.segment_committed', 'recording.finalizing', 'recording.ready', 'recording.failed', 'recording.deleted', 'schedule.created','schedule.updated','schedule.starting','schedule.started','schedule.missed','schedule.cancelled','schedule.failed','schedule.completed','schedule.reminder','restream.probing','restream.source_connected','restream.source_lost','restream.recovering','restream.stopped','restream.failed','clip.requested','clip.rendering','clip.ready','clip.failed','clip.deleted','mixer.started','mixer.scene_activated','mixer.source_lost','mixer.overloaded','mixer.stopped','mixer.failed','dvr.enabled','dvr.window_changed','dvr.segment_evicted','dvr.disabled'));
ALTER TABLE webhook_endpoint DROP CONSTRAINT webhook_endpoint_event_types_check;
ALTER TABLE webhook_endpoint ADD CONSTRAINT webhook_endpoint_event_types_check CHECK(cardinality(event_types) BETWEEN 1 AND 64 AND array_position(event_types,NULL) IS NULL AND event_types <@ ARRAY['room.created', 'room.started', 'room.ended', 'participant.joined', 'participant.left', 'participant.reconnected', 'track.published', 'track.unpublished', 'connection.degraded', 'connection.recovered', 'stream.created', 'stream.starting', 'stream.live', 'stream.reconnecting', 'stream.ended', 'stream.failed', 'broadcast.created', 'broadcast.starting', 'broadcast.live', 'broadcast.reconnecting', 'broadcast.output_degraded', 'broadcast.stopped', 'broadcast.failed', 'destination.created', 'destination.connected', 'destination.disconnected', 'destination.retrying', 'destination.failed', 'recording.started', 'recording.segment_committed', 'recording.finalizing', 'recording.ready', 'recording.failed', 'recording.deleted', 'schedule.created','schedule.updated','schedule.starting','schedule.started','schedule.missed','schedule.cancelled','schedule.failed','schedule.completed','schedule.reminder','restream.probing','restream.source_connected','restream.source_lost','restream.recovering','restream.stopped','restream.failed','clip.requested','clip.rendering','clip.ready','clip.failed','clip.deleted','mixer.started','mixer.scene_activated','mixer.source_lost','mixer.overloaded','mixer.stopped','mixer.failed','dvr.enabled','dvr.window_changed','dvr.segment_evicted','dvr.disabled']::text[]);



ALTER TABLE recording_segment ADD COLUMN discontinuity_sequence integer NOT NULL DEFAULT 0;
UPDATE recording_segment s SET discontinuity_sequence=t.n FROM (SELECT recording_id,position,sum(CASE WHEN discontinuity THEN 1 ELSE 0 END) OVER(PARTITION BY recording_id ORDER BY position) AS n FROM recording_segment) t WHERE s.recording_id=t.recording_id AND s.position=t.position;
CREATE FUNCTION recording_discontinuity_sequence() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 NEW.discontinuity_sequence:=coalesce((SELECT discontinuity_sequence FROM recording_segment WHERE recording_id=NEW.recording_id ORDER BY position DESC LIMIT 1),0)+CASE WHEN NEW.discontinuity THEN 1 ELSE 0 END; RETURN NEW; END $$;
CREATE TRIGGER recording_discontinuity_sequence_guard BEFORE INSERT ON recording_segment FOR EACH ROW EXECUTE FUNCTION recording_discontinuity_sequence();
